const questions = document.querySelectorAll(".question");
const submitButton = document.querySelector("#submitBtn");

questions.forEach((question) => {
  question.querySelectorAll(".option").forEach((option) => {
    option.addEventListener("click", () => {
      question.querySelectorAll(".option").forEach((item) => item.classList.remove("selected"));
      option.classList.add("selected");
    });
  });
});

submitButton.addEventListener("click", () => {
  const unansweredQuestion = [...questions].find(
    (question) => !question.querySelector(".option.selected")
  );

  if (unansweredQuestion) {
    unansweredQuestion.scrollIntoView({ behavior: "smooth", block: "center" });
    return;
  }

  let result = document.querySelector(".demo-result");

  if (!result) {
    result = document.createElement("p");
    result.className = "demo-result";
    submitButton.insertAdjacentElement("afterend", result);
  }

  result.textContent = "نسخة تجريبية للمحفظة — لم يتم إرسال أو حفظ أي بيانات.";
});
